<?php
require_once __DIR__.'/../includes/functions.php';require_role(['super_admin','admin']);$db=db();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$from=date('Y-m-01');$to=date('Y-m-d');}$s=$db->prepare('SELECT COUNT(*) total FROM appointments WHERE appointment_date BETWEEN ? AND ?');$s->execute([$from,$to]);$apptCount=(int)$s->fetchColumn();$s=$db->prepare("SELECT COUNT(*) FROM appointments WHERE appointment_date BETWEEN ? AND ? AND status='completed'");$s->execute([$from,$to]);$completed=(int)$s->fetchColumn();$s=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE paid_at>=? AND paid_at<?');$s->execute([$from.' 00:00:00',date('Y-m-d',strtotime($to.' +1 day')).' 00:00:00']);$revenue=(float)$s->fetchColumn();$popular=$db->prepare("SELECT dep.name,COUNT(*) total FROM appointments a JOIN doctors d ON d.id=a.doctor_id JOIN departments dep ON dep.id=d.department_id WHERE a.appointment_date BETWEEN ? AND ? GROUP BY dep.id ORDER BY total DESC");$popular->execute([$from,$to]);$deptRows=$popular->fetchAll();$pageTitle='Reports';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/page.php';page_heading('Insights','Clinic reports','Operational summary for a selected date range');?>
<div class="card mb-4"><div class="card-body"><form class="row g-3 align-items-end"><div class="col-md-4"><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?=e($from)?>" required></div><div class="col-md-4"><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?=e($to)?>" required></div><div class="col-md-4"><button class="btn btn-primary">Generate report</button></div></form></div></div><div class="row g-3 mb-4"><div class="col-md-4"><?=stat_card('Appointments',(string)$apptCount,'calendar-check',$from.' to '.$to)?></div><div class="col-md-4"><?=stat_card('Completed',(string)$completed,'check-circle','Completed appointments')?></div><div class="col-md-4"><?=stat_card('Payments received',money($revenue),'cash-coin','Based on recorded payments')?></div></div><div class="card"><div class="card-header"><h2 class="section-title">Appointments by department</h2></div><div class="table-responsive"><table class="table"><thead><tr><th>Department</th><th>Appointments</th></tr></thead><tbody><?php foreach($deptRows as $d):?><tr><td><?=e($d['name'])?></td><td><strong><?= (int)$d['total']?></strong></td></tr><?php endforeach;?><?php if(!$deptRows)echo empty_row(2,'No appointments in this period.');?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>